from pathlib import Path
root=Path('/workspace')
parent=ast.parse((root/'history_g0_r0076_parallel_restored.py').read_text())
files=['candidate.py','half_parallel_restored.py','half_orthogonal_raw.py','half_parallel_raw.py']
summary={}
base_model=next(n for n in parent.body if isinstance(n,ast.ClassDef) and n.name=='Model')
base_methods={n.name:ast.dump(n,include_attributes=False) for n in base_model.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))}
base_summary=ast.dump(next(n for n in parent.body if isinstance(n,ast.ClassDef) and n.name=='_SummaryProductVJP'),include_attributes=False)
normalized=[]
for file in files:
 data=(root/file).read_bytes(); t=ast.parse(data); compile(t,file,'exec')
 cfg=ast.literal_eval(next(n.value for n in t.body if isinstance(n,ast.Assign) and any(isinstance(a,ast.Name) and a.id=='CONFIG' for a in n.targets)))
 model=next(n for n in t.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 for n in model.body:
  if isinstance(n,ast.FunctionDef) and n.name"'!='"'__init__':assert ast.dump(n,include_attributes=False)==base_methods[n.name],n.name
 assert ast.dump(next(n for n in t.body if isinstance(n,ast.ClassDef) and n.name=='_SummaryProductVJP'),include_attributes=False)==base_summary
 init=next(n for n in model.body if isinstance(n,ast.FunctionDef) and n.name=='__init__')
 defaults=dict(zip([a.arg for a in init.args.args][-len(init.args.defaults):],init.args.defaults))
 assert ast.literal_eval(defaults['buy_context_vjp'])==cfg['buy_context_vjp']
 for n in ast.walk(t):
  if isinstance(n,ast.Import):assert all(a.name.split('.')[0] in {'torch'} for a in n.names)
  if isinstance(n,ast.ImportFrom):assert n.module.split('.')[0] in {'torch','unirank'}
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name):assert n.func.id not in {'open','eval','exec','compile','__import__'}
 # Remove exactly two variant-specific literals before cross-cell comparison.
 n=copy.deepcopy(t)
 for node in ast.walk(n):
  if isinstance(node,ast.Assign) and any(isinstance(a,ast.Name) and a.id=='CONFIG' for a in node.targets):
