    if ast.literal_eval(key)=='buy_context_vjp':node.value.values[i]=ast.Constant('CELL')
  if isinstance(node,ast.FunctionDef) and node.name=='__init__':
   idx=[a.arg for a in node.args.args][-len(node.args.defaults):].index('buy_context_vjp');node.args.defaults[idx]=ast.Constant('CELL')
 normalized.append(ast.dump(n,include_attributes=False))
 summary[file]={'source_sha256':hashlib.sha256(data).hexdigest(),'mode':cfg['buy_context_vjp'],'syntax':'passed','unchanged_model_methods_except_constructor':len(base_methods)-1,'unchanged_summary_vjp':True,'cross_cell_structure':'passed'}
assert len(set(normalized))==1
