 np=norm(p);nn=norm(n)
 if np==0 or nn==0:return None
 u=[x/np for x in p];d=sum(x*y for x,y in zip(n,u));a=[d*x for x in u];o=[x-y for x,y in zip(n,a)]
 if min(norm(a),norm(o))<=1e-6*nn:return None
 return a,o
rng=random.Random(77001);checked=0
